escenas.animacion:
const W = A.W, acc = A.accent;
A.bg('#0b1630', '#1b2238');
const kDes = A.k('desierto', 0.667), kSeco = A.k('seco', 1.333), kMundo = A.k('mundo', 2.0);
const kGente = A.k('gente', 2.667), kSaca = A.k('saca', 3.333), kAgua = A.k('agua', 3.667), kAire = A.k('aire', 4.333);

const cam = A.lerp(1, 1.07, A.p(0, A.dur, 'cruise'));
const shk = (t > kMundo && t < kMundo + 0.25) ? 6 : 0;

A.with(() => {
  // sol
  const sp = A.pop(kDes - 0.1, 0.55);
  if (sp > 0) {
    A.circle(800, 560, 150 * sp, { fill: acc, alpha: 0.12 + 0.05 * Math.sin(t * 6) });
    A.sun(800, 560, 70 * sp);
  }
  // dunas
  const up = A.lerp(380, 0, A.p(0, 0.9, 'snapSettle'));
  const sample = (y0, cps, n) => {
    const pts = [];
    for (let i = 0; i <= n; i++) {
      const x = -40 + (1160 * i) / n;
      let y = y0;
      for (const c of cps) y += c[0] * Math.sin(x * c[1] + c[2]);
      pts.push([x, y + up]);
    }
    return pts;
  };
  const back = sample(860, [[45, 0.006, 0.5], [20, 0.013, 2]], 40);
  const backPoly = back.concat([[1120, 1130 + up], [-40, 1130 + up]]);
  ctx.beginPath(); backPoly.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.closePath();
  ctx.fillStyle = '#9a6a2e'; ctx.fill();
  A.lib.hatch(ctx, backPoly, { angle: 0.6, spacing: 16, width: 1.5, color: 'rgba(40,20,5,0.35)' });
  const front = sample(960, [[35, 0.005, 2.2], [12, 0.017, 0.3]], 40);
  const frontPoly = front.concat([[1120, 1130 + up], [-40, 1130 + up]]);
  ctx.beginPath(); frontPoly.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.closePath();
  ctx.fillStyle = '#d49a48'; ctx.fill();
  A.line(front, { stroke: '#ffe2a8', lw: 3, alpha: 0.8 });

  // brillo de calor
  const ha = A.p(kDes, 0.6, 'softInOut') * (1 - A.p(kSaca, 0.5, 'softInOut'));
  for (let j = 0; j < 3; j++) {
    const pts = [];
    for (let x = 120; x <= 960; x += 30) pts.push([x, 900 - j * 26 + up + 6 * Math.sin(x * 0.03 + t * 7 + j)]);
    A.line(pts, { stroke: '#ffe9b0', lw: 2, alpha: 0.25 * ha, dash: [10, 14] });
  }

  // grietas
  const r = A.rand(7);
  for (let c = 0; c < 7; c++) {
    let x = 90 + c * 150 + r() * 60, y = 1010 + r() * 50;
    const pts = [[x, y + up]];
    for (let s = 0; s < 5; s++) { x += (r() - 0.5) * 70 + 18; y += (r() - 0.5) * 40; pts.push([x, y + up]); }
    A.line(pts, { stroke: '#4a2a10', lw: 4, progress: A.p(kSeco + c * 0.05, 0.5, 'glide') });
  }

  // persona
  const pp = A.pop(kGente - 0.05, 0.5);
  if (pp > 0) A.person(330, 1060, { scale: 1.4 * pp, color: '#ffffff' });

  // humedad invisible -> se junta en una gota
  const tx = 380, ty = 700;
  const vis = A.p(kSaca - 0.35, 0.4, 'softInOut');
  const conv = A.p(kSaca, 0.75, 'glide');
  if (vis > 0) {
    A.particles(46, 11, (i, rnd) => {
      const ox = 80 + rnd() * 920, oy = 470 + rnd() * 380;
      const wob = Math.sin(t * 2 + i) * 12;
      const x = A.lerp(ox + wob, tx, conv), y = A.lerp(oy, ty, conv);
      A.circle(x, y, 5 + rnd() * 5, { fill: '#bfe6ff', alpha: vis * (1 - conv * 0.9), glow: 10 });
    });
  }
  const dp = A.pop(kAgua - 0.05, 0.5);
  if (dp > 0) {
    const bump = 1 + 0.15 * (A.pop(kAire, 0.4) - A.p(kAire, 0.4, 'cruise'));
    A.lib.glowDot(ctx, tx, ty, 90 * dp, { color: '#7fd0ff' });
    A.drop(tx, ty, 55 * dp * bump, { fill: '#5bc0ff', stroke: '#ffffff' });
  }
  if (t > kAire) A.rings(tx, ty, kAire, { count: 3, speed: 380, gap: 60, maxR: 280, color: acc, lw: 5 });
}, { x: 540, y: 820, scale: cam, shake: shk });

A.flash(kAire, 0.25, 0.35);

// zona secundaria
const lp = A.p(kSeco, 0.5, 'softLand') * (1 - A.p(kGente + 0.4, 0.4, 'accelExit'));
if (lp > 0) {
  const cnt = A.counter(100, 1, A.p(kSeco, 1.0, 'glide'), 0);
  A.text('LLUVIA', 540, 1400, { size: 46, color: '#ffffff', weight: 800, align: 'center', alpha: lp });
  A.text('≈' + cnt + ' mm/año', 540, 1500, { size: 96, color: acc, weight: 900, align: 'center', alpha: lp });
  const mp = A.pop(kMundo - 0.05, 0.45);
  if (mp > 0) A.label('EL MÁS SECO DEL MUNDO', 540, 1630, { size: 50, bg: '#e2483d', color: '#ffffff', scale: mp, alpha: lp });
}
const ap = A.pop(kAire - 0.05, 0.5);
if (ap > 0) A.label('¡DEL AIRE!', 540, 1530, { size: 96, bg: acc, color: '#0b1630', scale: ap });

const W=A.W, acc=A.accent;
A.bg('#06121f','#0b2233',true);
const kC=A.k('costa',0.67), kN=A.k('norte',1.33), kCam=A.k('camanchaca:',2.67), kE=A.k('espesa',3.67);
const kL=A.k('llega',4.33), kM=A.k('mar',5.33), kCh=A.k('choca',6.0), kCe=A.k('cerros.',7.0);

const zoom = A.lerp(1.0,1.06,A.clamp(t/A.dur));
A.with(()=>{
  // ---- MAR ----
  const seaP = A.p(0,0.8,'softLand');
  const g = ctx.createLinearGradient(0,960,0,1120);
  g.addColorStop(0,'rgba(77,208,225,0.35)'); g.addColorStop(1,'rgba(10,40,70,0.9)');
  ctx.save(); ctx.globalAlpha=seaP; ctx.fillStyle=g; ctx.fillRect(-60,960,640,180); ctx.restore();
  for(let w=0;w<3;w++){
    const pts=[]; const yy=975+w*40;
    for(let x=-40;x<=560;x+=20) pts.push([x, yy+Math.sin(x*0.03+t*2.2+w)*6]);
    A.line(pts,{stroke:acc,lw:3-w*0.6,alpha:Math.max(0,0.7*seaP-w*0.15)});
  }
  // ---- CERROS ----
  const shake = t>kCh ? 12*(1-A.p(kCh,0.5,'cruise')) : 0;
  const hill=[[470,990],[560,940],[640,820],[720,700],[800,640],[880,680],[960,600],[1040,640],[1140,660],[1140,1140],[470,1140]];
  const hp = A.p(kC-0.3,1.0,'softLand');
  A.with(()=>{
    ctx.save(); ctx.globalAlpha=hp;
    ctx.beginPath(); hill.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath();
    const hg=ctx.createLinearGradient(0,600,0,1120); hg.addColorStop(0,'#3a2f2a'); hg.addColorStop(1,'#1a1512');
    ctx.fillStyle=hg; ctx.fill(); ctx.restore();
    if(hp>0.5) A.lib.hatch(ctx,hill,{angle:45,spacing:16,width:1.5,color:'rgba(255,220,180,'+(0.18*hp)+')'});
    A.line(hill.slice(0,9),{stroke:'#f2e6d8',lw:5,progress:A.p(kC-0.2,1.0,'glide')});
  },{x:800,y:900,shake});
  A.line([[-40,960],[560,960]],{stroke:'#ffffff',lw:2,alpha:0.4*seaP,dash:[10,10]});

  // ---- NIEBLA: entra desde la izquierda desde el inicio ----
  const enter = A.p(0.2, Math.max(0.8,kCam+0.4), 'glide');
  const dens = 0.35*A.p(0.2,1.6,'softLand') + 0.25*A.p(kCam,0.8,'softLand') + 0.4*A.p(kE,0.9,'softLand');
  const move = A.p(kL,1.7,'glide');
  const pile = A.p(kCh,1.0,'softLand');
  const cx = A.lerp(-220,260,enter) + (560-260)*move;
  const cy = A.lerp(950,830,enter);
  const wallX = y => y>940?560:(y<700?740:560+(940-y)*(180/240));
  const N=80;
  ctx.save();
  for(let i=0;i<N;i++){
    const r=A.rand(i*7+3);
    const dx=(r()-0.5)*480, dy=(r()-0.5)*170, rad=40+r()*55, ph=r()*6.28;
    const vis = A.clamp((dens*N - i)/4);
    if(vis<=0) continue;
    let x = cx + dx*(1-0.35*pile) + Math.sin(t*0.7+ph)*14;
    let y = cy + dy + Math.cos(t*0.5+ph)*8;
    const lim = wallX(y) - rad*0.35;
    if(x>lim){ const over=x-lim; x=lim; y-=over*0.55; }
    const gr=ctx.createRadialGradient(x,y,0,x,y,rad);
    gr.addColorStop(0,'rgba(225,245,250,'+(0.22*vis)+')'); gr.addColorStop(1,'rgba(225,245,250,0)');
    ctx.fillStyle=gr; ctx.beginPath(); ctx.arc(x,y,rad,0,6.283); ctx.fill();
  }
  ctx.restore();
  A.particles(40,11,(i,rnd)=>{
    const vis=A.clamp((dens*40-i)/3); if(vis<=0) return;
    let x=cx+(rnd()-0.5)*420*(1-0.3*pile)+Math.sin(t+i)*20, y=cy+(rnd()-0.5)*150;
    const lim=wallX(y)-10; if(x>lim){y-=(x-lim)*0.55;x=lim;}
    A.circle(x,y,3,{fill:acc,alpha:0.8*vis});
  });
  // flechas de viento
  if(t>kL){
    for(let j=0;j<3;j++){
      const ap=A.p(kL+j*0.15,0.7,'glide'), fade=1-A.p(kCh,0.4,'accelExit');
      const yy=760+j*70, x0=Math.max(30,cx-260);
      A.arrow(x0,yy,x0+170,yy,{progress:ap,color:acc,lw:5,head:16,alpha:0.9*fade});
    }
  }
  if(t>kCh){
    A.rings(650,820,kCh,{count:3,speed:420,gap:60,maxR:260,color:acc,lw:5,alpha:0.8});
  }
  // etiqueta CAMANCHACA fija, centrada sobre la niebla
  const lc=A.pop(kCam,0.5);
  if(lc>0) A.label('CAMANCHACA',500,760,{size:54,bg:acc,color:'#06121f',scale:lc});
  // ESPESA
  const le=A.pop(kE,0.45)*(1-A.p(kL,0.4,'accelExit'));
  if(le>0.01) A.label('ESPESA',Math.max(180,cx),1040,{size:40,bg:'#ffffff',color:'#06121f',scale:le});
  // brújula norte
  const ln=A.pop(kN,0.45);
  if(ln>0) A.with(()=>{
    A.circle(120,500,46,{stroke:'#ffffff',lw:3,alpha:0.8});
    A.arrow(120,530,120,468,{color:acc,lw:6,head:18});
    A.text('N',120,440,{size:34,color:'#ffffff',weight:800,align:'center'});
  },{x:120,y:500,scale:ln});
},{x:540,y:820,scale:zoom});
A.flash(kCh,0.25,0.35);

// ---- ZONA SECUNDARIA: MAR → CERRO ----
const ap = A.p(kM-0.4,0.8,'whip');
if(ap>0){
  const hit = t>kCh;
  A.text('MAR',170,1500,{size:46,color:acc,weight:800,align:'center',alpha:A.p(kM-0.4,0.4)});
  A.text('CERRO',910,1500,{size:46,color:'#f2e6d8',weight:800,align:'center',alpha:A.p(kCh-0.2,0.4)});
  A.arrow(270,1485,A.lerp(270,780,ap),1485,{progress:1,color:'#ffffff',lw:8,head:26});
  const s1=A.pop(kM,0.45)*(1-A.p(kCh,0.3,'accelExit'));
  if(s1>0.01) A.label('DESDE EL MAR',525,1600,{size:40,bg:acc,color:'#06121f',scale:s1});
  const s2=A.pop(kCh+0.1,0.45);
  if(hit&&s2>0) A.with(()=>{A.label('¡CHOCA!',525,1600,{size:52,bg:'#ffffff',color:'#06121f'});},{x:525,y:1600,scale:s2,shake:t<kCh+0.4?6:0});
}

const W=A.W, acc=A.accent;
A.bg('#06121c','#0b2433');
const tN=A.k('niebla',0.33), tM=A.k('millones',1.0), tG=A.k('gotitas',1.67), tP=A.k('pequeñas',2.33), tF=A.k('flotan',3.0), tA=A.k('aire,',4.0), tNo=A.k('no',4.67), tC=A.k('caen',5.0), tL=A.k('lluvia.',5.67);
const win=(a,b)=>A.p(a,0.35,'softInOut')*(1-A.p(b,0.3,'softInOut'));
const fmt=v=>String(Math.floor(v)).replace(/\B(?=(\d{3})+(?!\d))/g,'.');

// --- NIEBLA: manchas suaves ---
const fogA=A.p(tN-0.2,0.8,'softInOut')*(1-0.6*A.p(tM,0.9,'softInOut'));
for(let i=0;i<10;i++){
  const r=A.rand(i+11);
  const x=80+r()*920+Math.sin(t*0.5+i)*40, y=470+r()*620, rad=170+r()*150;
  const g=ctx.createRadialGradient(x,y,0,x,y,rad);
  g.addColorStop(0,'rgba(210,235,245,'+(0.22*fogA)+')');
  g.addColorStop(1,'rgba(210,235,245,0)');
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(x,y,rad,0,Math.PI*2); ctx.fill();
}
if(fogA>0.01) A.text('NIEBLA',540,790,{size:96,weight:900,color:'#ffffff',align:'center',alpha:A.p(tN,0.4,'softLand')*(1-A.p(tM,0.3,'softInOut'))});

// --- MILLONES de gotitas flotando ---
const N=170, vis=Math.floor(A.lerp(0,N,A.p(tM,1.0,'glide')));
for(let i=0;i<vis;i++){
  const r=A.rand(i*7+3);
  const sp=10+r()*25;
  let x=(r()*1180+t*sp)%1180-50;
  const y=440+r()*660+Math.sin(t*1.4+r()*6)*10;
  const rr=2+r()*3.5;
  ctx.globalAlpha=0.55+0.4*r();
  ctx.fillStyle=acc; ctx.beginPath(); ctx.arc(x,y,rr,0,Math.PI*2); ctx.fill();
}
ctx.globalAlpha=1;

// --- Lupa (protagonista) ---
const mv=A.p(tNo,0.7,'glide');
const lx=A.lerp(540,300,mv), ly=A.lerp(770,760,mv), ls=A.lerp(1,0.72,mv);
const lensS=A.pop(tG,0.5);
if(t>=tG){
  ctx.save(); ctx.translate(lx,ly); ctx.scale(ls*lensS,ls*lensS);
  // mango
  A.line([[165,165],[290,290]],{stroke:'#ffffff',lw:30});
  A.circle(0,0,230,{fill:'#071a26',stroke:'#ffffff',lw:10,glow:18});
  // gotita ampliada
  const z=A.p(tG+0.1,0.7,'snapSettle');
  const bob=t>tF?Math.sin((t-tF)*3)*14:0;
  const dr=A.lerp(5,85,z), dy=bob;
  const g=ctx.createRadialGradient(-dr*0.35,dy-dr*0.35,dr*0.1,0,dy,dr);
  g.addColorStop(0,'#e8fbff'); g.addColorStop(0.5,acc); g.addColorStop(1,'#0e6b78');
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(0,dy,dr,0,Math.PI*2); ctx.fill();
  A.circle(0,dy,dr,{stroke:'#ffffff',lw:4,alpha:0.8});
  // fuerzas
  const fu=A.p(tF,0.5,'snapSettle');
  if(fu>0){
    A.arrow(0,dy+dr+12,0,dy+dr+12+55*fu,{color:'#ffffff',lw:8,head:20});
    A.text('PESO',-30,dy+dr+60,{size:34,weight:800,color:'#ffffff',align:'right',alpha:fu});
  }
  const fa=A.p(tA-0.6,0.5,'snapSettle');
  if(fa>0){
    A.arrow(0,dy-dr-12,0,dy-dr-12-55*fa,{color:acc,lw:8,head:20});
    A.text('AIRE',-30,dy-dr-40,{size:34,weight:800,color:acc,align:'right',alpha:fa});
    if(t>tA-0.6) A.rings(0,dy,tA-0.6,{count:2,speed:120,gap:0.5,maxR:200,color:acc,lw:3,alpha:0.4});
  }
  ctx.restore();
  // etiqueta de tamaño
  const pl=A.pop(tP,0.45);
  if(pl>0) A.label('0,01 mm',lx,ly-260*ls-10,{size:46,bg:acc,color:'#06121c',scale:pl,alpha:1-A.p(tNo,0.3)});
}

// --- LLUVIA que sí cae ---
const rA=A.p(tC-0.15,0.3,'softLand');
if(rA>0){
  const xs=[700,810,920], ph=[0,0.33,0.66];
  for(let j=0;j<3;j++){
    const yy=450+(((t-tC)*1.4+ph[j])%1)*640;
    A.line([[xs[j],yy-150],[xs[j],yy-30]],{stroke:'#ffffff',lw:4,alpha:0.35*rA});
    ctx.globalAlpha=rA;
    A.drop(xs[j],yy,30,{fill:'#ffffff',stroke:acc});
    ctx.globalAlpha=1;
  }
  const pl=A.pop(tL,0.45);
  if(pl>0){
    A.label('LLUVIA: CAE',810,1095,{size:44,bg:'#ffffff',color:'#06121c',scale:pl});
    A.label('GOTITA: FLOTA',300,1095,{size:44,bg:acc,color:'#06121c',scale:pl});
  }
  A.flash(tL,0.25,0.25);
}

// --- Zona secundaria ---
// 1) contador
const c1=win(tM,tP);
if(c1>0.01){
  A.text(fmt(1000000*A.p(tM,1.1,'glide')),540,1530,{size:110,weight:900,color:acc,align:'center',alpha:c1});
  A.text('gotitas por cada litro de aire',540,1610,{size:38,color:'#ffffff',align:'center',alpha:c1*0.85});
}
// 2) comparación de tamaño
const c2=win(tP+0.1,tC-0.1);
if(c2>0.01){
  A.text('Más finas que un cabello',540,1400,{size:44,weight:800,color:'#ffffff',align:'center',alpha:c2});
  A.circle(380,1540,4,{fill:acc,glow:12,alpha:c2});
  A.rings(380,1540,tP+0.2,{count:2,speed:40,gap:0.6,maxR:50,color:acc,lw:2,alpha:0.5*c2});
  A.text('gotita',380,1650,{size:36,color:acc,align:'center',alpha:c2});
  const hh=170*A.p(tP+0.25,0.6,'softLand');
  A.rect(690,1540-hh/2,22,hh,{r:11,fill:'#e9e2d0',alpha:c2});
  A.text('cabello',700,1650,{size:36,color:'#ffffff',align:'center',alpha:c2});
}
// 3) velocidad de caída
const c3=A.p(tC,0.35,'softLand');
if(c3>0){
  A.text('Velocidad de caída',540,1395,{size:42,weight:800,color:'#ffffff',align:'center',alpha:c3});
  A.text('gotita',140,1490,{size:38,color:acc,align:'left',alpha:c3});
  A.rect(300,1462,12*A.p(tC+0.1,0.4),36,{r:8,fill:acc,alpha:c3});
  A.text('1 cm/s',330,1490,{size:38,weight:700,color:acc,align:'left',alpha:c3});
  A.text('lluvia',140,1610,{size:38,color:'#ffffff',align:'left',alpha:c3});
  const bw=560*A.p(tC+0.15,0.8,'whip');
  A.rect(300,1582,bw,36,{r:8,fill:'#ffffff',alpha:c3});
  A.text('9 m/s',300+bw-10,1660,{size:38,weight:700,color:'#ffffff',align:'right',alpha:A.p(tC+0.6,0.3)});
}

const W=A.W, ac=A.accent;
A.bg('#06121f','#0b2233');
const kPon=A.k('poner',1.0), kMal=A.k('malla',1.667), kVer=A.k('vertical',2.0), kCam=A.k('camino,',3.0), kRed=A.k('red',4.0), kVol=A.k('vóleibol',4.667), kGig=A.k('gigante.',5.0);
const G=1080;
// mar
ctx.save();
ctx.fillStyle='#0d3550';ctx.fillRect(0,G-10,300,40);
ctx.strokeStyle='#4fa3d1';ctx.lineWidth=4;ctx.beginPath();
for(let x=0;x<=300;x+=10){const y=G-10+Math.sin(x*0.05+t*3)*5; x?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();ctx.restore();
// cerros
const hill=[[760,G],[860,940],[940,980],[1010,860],[1080,820],[1080,G]];
A.lib.inkPath(ctx,hill,{width:4,color:'#cfe3f0',closed:true,fill:'#12293a'});
A.lib.hatch(ctx,hill,{angle:0.8,spacing:16,width:1.5,color:'rgba(160,200,230,0.35)'});
A.line([[300,G],[1080,G]],{stroke:'#cfe3f0',lw:4});
// malla geometria (3/4)
const fx=540,bx=640,top=560,bot=900,sk=40;
const poleP=A.p(kPon,0.5,'crashIn');
const meshP=A.p(kMal,0.7,'softLand');
const caughtT=kCam;
// postes
if(poleP>0){
  const dy=(1-poleP)*-700;
  A.with(()=>{
    A.line([[fx,top-20+dy],[fx,G+dy]],{stroke:'#ffffff',lw:10});
    A.line([[bx,top-20-sk+dy],[bx,G-sk+dy]],{stroke:'#ffffff',lw:8});
  },{shake:A.p(kPon+0.45,0.3,'crashOut')>0&&A.p(kPon+0.45,0.3,'crashOut')<1?8:0});
  if(t>kPon+0.45) A.rings(fx,G,kPon+0.45,{count:2,maxR:120,color:'#ffffff',lw:3});
}
// fondo de la malla (relleno)
if(meshP>0){
  const yb=A.lerp(top,bot,meshP);
  ctx.save();ctx.fillStyle='rgba(124,252,0,0.10)';ctx.beginPath();
