let bx = A.lerp(A.lerp(A.lerp(540, 160, m1), 760, m2), MX, m3);
let by = A.lerp(A.lerp(A.lerp(720, 560, m1), 560, m2), MY, m3);
const bs = A.lerp(A.lerp(A.lerp(2.2, 0.9, m1), 1.6, m2), 0, m3) * bulbP;
if (m2 > 0.3) A.lib.glowDot(ctx, 160, 560, 14, { color: acc });
if (bs > 0.02) {
  A.bulb(bx, by, { scale: bs, on: A.p(kIdea + 0.15, 0.3, 'softInOut') });
  if (t > kIdea && t < kChile + 0.5) A.rings(bx, by, kIdea + 0.15, { count: 2, color: acc, maxR: 220, lw: 3 });
}

const tM = kDes + 0.4;
const pm = A.p(tM, 0.9, 'softLand');
if (pm > 0) {
  const mainSc = A.lerp(0.25, 1, A.p(tM, 0.6, 'snapSettle'));
  mesh(MX, MY, mainSc, pm, 1);
  if (t > tM && t < tM + 0.8) A.rings(MX, MY, tM, { count: 2, color: acc, maxR: 240, lw: 3 });
  if (t > tM + 0.6) {
    for (let j = 0; j < 5; j++) {
      const ph = ((t - tM - 0.6) * 0.7 + j * 0.23) % 1;
      A.drop(MX - 130 + 260 * (j + 0.5) / 5, MY - 100 + ph * 200, 5 + ph * 7, { fill: '#7fd3ff' });
    }
  }
  const lb = A.p(tM + 0.4, 0.5, 'snapSettle');
  if (lb > 0) A.label('ATRAPANIEBLAS', MX, 600, { size: 32, bg: '#1d3a66', color: '#fff', scale: lb });
}

// ---------- AÑOS 50 ----------
const yIn = A.p(kDes + 0.3, 0.5, 'softLand');
const yOut = 1 - A.p(kDono, 0.45, 'accelExit');
if (yIn > 0 && yOut > 0) {
  const pc2 = A.p(kDes + 0.3, kCin - kDes - 0.3, 'softInOut');
  const yp = A.pop(kCin, 0.5);
  const txt = t < kCin ? A.counter(1900, 1950, pc2, 0) : '1950s';
  const sc = t < kCin ? 1 : yp;
  A.with(() => {
    A.text('AÑOS', 540, 1390, { size: 46, color: A.pal.paleBlue, weight: 700, align: 'center' });
    A.text(txt, 540, 1530, { size: 180, color: t < kCin ? '#fff' : acc, weight: 900, align: 'center' });
  }, { x: 540, y: 1480, scale: sc, alpha: yIn * yOut });
  if (t > kCin) A.rings(540, 1480, kCin, { count: 2, color: acc, maxR: 380, lw: 4 });
}

// ---------- DONÓ (cinta diagonal sobre el borde inferior de la malla) ----------
const st = A.p(kDono, 0.35, 'crashIn');
if (st > 0) {
  const shake = t < kDono + 0.4 ? 8 * (1 - A.p(kDono + 0.2, 0.25)) : 0;
  A.with(() => A.label('DONADO', MX, 892, { size: 50, bg: acc, color: '#fff' }), { x: MX, y: 892, scale: A.lerp(2.0, 1, st), rot: -0.12, alpha: st, shake });
  if (t > kDono + 0.2) A.rings(MX, 892, kDono + 0.2, { count: 2, color: acc, maxR: 220, lw: 4 });
}
A.flash(kDono + 0.2, 0.25, 0.2);

// ---------- COPIAS PARA CUALQUIERA ----------
const dashFade = 1 - A.p(kInv + 0.8, 0.5, 'softInOut');
for (let i = 0; i < 5; i++) {
  const tx = 140 + i * 200, ty = 1530;
  const pi = A.p(kInv + i * 0.1, 0.75, 'whip');
  if (pi <= 0) continue;
  if (dashFade > 0) A.line([[MX, MY + 100], [A.lerp(MX, tx, 0.5), 1360], [tx, ty]], { stroke: acc, lw: 3, dash: [10, 12], alpha: 0.5 * dashFade, progress: pi });
  const arc = Math.sin(pi * Math.PI) * -80;
  const x = A.lerp(MX, tx, pi), y = A.lerp(MY, ty, pi) + arc;
  mesh(x, y, A.lerp(0.8, 0.4, pi), 1, A.clamp(pi * 3));
  const pq = A.pop(kCual + i * 0.07, 0.45);
  if (pq > 0) A.with(() => A.person(tx, 1730, { scale: 0.75, color: i % 2 ? '#ffffff' : A.pal.paleBlue }), { x: tx, y: 1730, scale: pq });
}
const lt = A.pop(kCual - 0.1, 0.5);
if (lt > 0) A.label('PARA TODOS', 540, 1390, { size: 58, bg: acc, color: '#fff', scale: lt });

const W=A.W, ac=A.accent, WATER='#9be7ff', AMB='#ffc93c';
A.bg('#06142b','#020812',true);
const kR=A.k('regar',1.333), kAg=A.k('agua',2.333), kCo=A.k('comunidades…',3.0), kH=A.k('hasta',3.667), kC=A.k('cerveza.',4.667);

const pB=A.p(kH,0.6,'whip');
// ---------- ESCENA DE USOS (huertos + comunidades) ----------
function usos(){
  // canaleta
  A.rect(140,450,800,44,{r:14,stroke:'#ffffff',lw:4});
  A.rect(150,466,780,22,{r:8,fill:WATER,alpha:0.55});
  for(let i=0;i<10;i++){const x=150+((i*80+t*220)%780);A.rect(x,472,30,6,{r:3,fill:'#ffffff',alpha:0.6});}
  // tubería rama izquierda (huertos)
  const pL=A.p(0.3,1.0,'glide');
  A.line([[540,494],[540,620],[270,620],[270,730]],{stroke:WATER,lw:12,progress:pL});
  // rama derecha (comunidades)
  const pR=A.p(kAg-0.3,0.7,'glide');
  A.line([[540,620],[810,620],[810,760]],{stroke:WATER,lw:12,progress:pR});
  // gotas cayendo al huerto
  if(t>kR){for(let i=0;i<4;i++){const ph=((t-kR)*1.6+i/4)%1;A.drop(270,740+ph*210,12,{fill:WATER});}}
  // tierra
  const soil=[[120,1010],[160,975],[270,955],[380,975],[420,1010]];
  A.lib.inkPath(ctx,soil.concat([[120,1010]]),{width:4,color:'#ffffff',closed:true,fill:'#3a2a1c'});
  A.lib.hatch(ctx,soil,{angle:0.6,spacing:12,width:1.5,color:'rgba(255,255,255,0.35)'});
  // brotes
  [200,270,340].forEach((x,i)=>{
    const g=A.p(kR+0.15+i*0.15,0.7,'popOver'); if(g<=0)return;
    const base=x===270?955:975, h=110*g;
    A.line([[x,base],[x,base-h]],{stroke:ac,lw:8});
    A.with(()=>{
      ctx.fillStyle=ac;
      ctx.beginPath();ctx.ellipse(x-24,base-h+10,26,12,-0.5,0,7);ctx.fill();
      ctx.beginPath();ctx.ellipse(x+24,base-h+2,26,12,0.5,0,7);ctx.fill();
    },{x:x,y:base-h,scale:g});
  });
  const lh=A.pop(kR+0.3);
  if(lh>0)A.label('HUERTOS',270,1080,{size:46,bg:ac,color:'#06142b',scale:lh});
  // estanque
  if(pR>0.95){
    A.rect(755,760,110,80,{r:10,stroke:'#ffffff',lw:4});
    const lv=A.p(kAg+0.2,0.9,'softInOut');
    if(lv>0)A.rect(761,834-66*lv,98,66*lv,{r:6,fill:WATER,alpha:0.8});
  }
  // casas
  const lit=A.p(kCo,0.4,'crashIn');
  [[730,0],[890,1]].forEach(([cx,j])=>{
    const pc=A.p(kAg+j*0.15,0.5,'snapSettle'); if(pc<=0)return;
    A.with(()=>{
      A.rect(cx-55,920,110,90,{stroke:'#ffffff',lw:4,fill:'#0c2246'});
      A.lib.inkPath(ctx,[[cx-68,922],[cx,868],[cx+68,922]],{width:4,color:'#ffffff'});
      A.rect(cx-35,945,28,28,{r:4,fill:lit>0?AMB:'#16305a',alpha:0.4+0.6*lit,glow:lit>0?20*lit:0});
      A.rect(cx+8,945,28,28,{r:4,fill:lit>0?AMB:'#16305a',alpha:0.4+0.6*lit,glow:lit>0?20*lit:0});
    },{x:cx,y:1010,scale:pc});
  });
  if(lit>0)A.rings(810,960,kCo,{count:2,speed:260,gap:0.25,maxR:200,color:AMB,lw:4,alpha:0.6});
  const lc=A.pop(kCo+0.1);
  if(lc>0)A.label('COMUNIDADES',810,1080,{size:46,bg:'#ffffff',color:'#06142b',scale:lc});
}
ctx.save();
const s=A.lerp(1,0.45,pB);
ctx.translate(540,A.lerp(760,1545,pB));ctx.scale(s,s);ctx.translate(-540,-760);
ctx.globalAlpha=A.lerp(1,0.75,pB);
usos();
ctx.restore();

// ---------- CERVEZA (protagonista final) ----------
const gA=A.p(kH+0.05,0.55,'snapSettle');
if(gA>0){
  const shake=t>kC&&t<kC+0.35?10*(1-(t-kC)/0.35):0;
  A.with(()=>{
    const T=560,B=1080,xl=(y)=>A.lerp(360,400,(y-T)/(B-T)),xr=(y)=>A.lerp(720,680,(y-T)/(B-T));
    // gota que cae al vaso
    const dp=A.p(kH+0.15,0.35,'gentleIn');
    if(dp>0&&dp<1)A.drop(540,A.lerp(420,1000,dp),18,{fill:WATER});
    // nivel de cerveza
    const f=A.p(kH+0.45,0.85,'softInOut');
    const lvl=A.lerp(B,640,f);
    if(f>0){
      const gr=ctx.createLinearGradient(0,lvl,0,B);gr.addColorStop(0,'#ffd75e');gr.addColorStop(1,'#d9861a');
      ctx.fillStyle=gr;ctx.beginPath();ctx.moveTo(xl(lvl)+6,lvl);ctx.lineTo(xr(lvl)-6,lvl);ctx.lineTo(xr(B)-6,B-6);ctx.lineTo(xl(B)+6,B-6);ctx.closePath();ctx.fill();
      // burbujas
      A.particles(18,7,(i,r)=>{
        const bx=A.lerp(xl(B)+30,xr(B)-30,r()),sp=60+r()*90,ph=r();
        const y=B-20-(((t*sp)+ph*400)%Math.max(1,B-lvl-20));
        if(y>lvl+8)A.circle(bx,y,3+r()*5,{stroke:'#fff6d0',lw:2,alpha:0.8});
      });
    }
    // espuma en "cerveza"
    const fo=A.pop(kC,0.5);
    if(fo>0){
      A.with(()=>{
        for(let i=0;i<7;i++){const x=A.lerp(xl(lvl)+20,xr(lvl)-20,i/6);
          A.circle(x,lvl-10-(i%2)*18,46,{fill:'#fffaf0'});}
        A.circle(xr(lvl)-10,lvl+40,22,{fill:'#fffaf0'});
      },{x:540,y:lvl,scale:fo});
    }
    // vaso
    A.lib.inkPath(ctx,[[360,T],[720,T],[680,B],[400,B]],{width:7,color:'#ffffff',closed:true});
    A.lib.hatch(ctx,[[372,T+20],[410,T+20],[440,B-20],[410,B-20]],{angle:1.2,spacing:10,width:2,color:'rgba(255,255,255,0.4)'});
    ctx.strokeStyle='#ffffff';ctx.lineWidth=7;ctx.beginPath();ctx.arc(720,800,95,-1.25,1.25);ctx.stroke();
  },{x:540,y:1080,scale:gA,shake:shake});
  if(t>kC){A.rings(540,640,kC,{count:3,speed:520,gap:0.12,maxR:520,color:ac,lw:6,alpha:0.7});A.flash(kC,0.25,0.45);}
  const lb=A.pop(kC+0.08,0.45);
  if(lb>0)A.with(()=>A.label('¡CERVEZA!',820,480,{size:64,bg:ac,color:'#06142b'}),{x:820,y:480,scale:lb,rot:-0.12});
}

const W=A.W, acc=A.accent;
A.bg('#0b1a2e','#050b16',true);
const tS=A.k('Síguenos',0), tCh=A.k('Chile',1.667), tMu=A.k('mundo.',2.667), tCo=A.k('¿Conocías',3.0), tAt=A.k('atrapanieblas?',3.667);
const tDraw=tS+1.2;
// niebla ambiental
A.particles(40,7,(i,r)=>{const sp=40+r()*60;const x=((r()*W+t*sp)%(W+200))-100;const y=430+r()*680;A.circle(x,y,18+r()*30,{fill:'#cfe3ff',alpha:0.05+0.04*r()});});
// boton seguir grande en el centro (protagonista inicial)
const tPress=tS+0.7;
const cOut=A.p(tS+1.1,0.3,'accelExit');
if(cOut<1){
  const bIn=A.pop(tS,0.45);
  A.with(()=>{A.follow(540,800,tS,tPress);},{x:540,y:800,scale:1.7*bIn*(1-0.3*cOut),alpha:1-cOut});
  if(t>tPress&&t<tPress+0.9)A.rings(540,800,tPress,{count:3,speed:500,gap:60,maxR:300,color:acc,lw:5,alpha:1-cOut});
}
// pildora final abajo: aparece directamente en su sitio
if(t>=tS+1.1){
  const pIn=A.pop(tS+1.1,0.45);
  A.with(()=>{A.follow(540,1620,tS-5,tS-4.5);},{x:540,y:1620,scale:pIn,alpha:A.clamp((t-tS-1.1)/0.2)});
}
// Chile + mundo
const out=A.p(tCo-0.05,0.35,'accelExit');
const chP=A.p(tDraw,0.8,'softLand');
if(t>=tDraw&&out<1){
A.with(()=>{
const pts=[[455,450],[490,455],[492,560],[485,680],[480,800],[470,920],[462,1010],[470,1080],[445,1100],[425,1060],[430,960],[440,840],[448,720],[452,600],[448,500]];
A.lib.inkPath(ctx,pts,{width:6,color:acc,closed:true,draw:chP});
if(chP>0.6){ctx.save();ctx.globalAlpha=(chP-0.6)/0.4;A.lib.hatch(ctx,pts,{angle:45,spacing:10,width:2,color:acc});ctx.restore();}
if(t>=tDraw+0.55)A.label('CHILE',370,1000,{size:44,bg:acc,color:'#0b1a2e',scale:A.pop(tDraw+0.55)});
const gStart=Math.min(tCh,tDraw+0.35);
if(t>=gStart){
  const gx=720,gy=760,gr=170*A.pop(gStart,0.5);
  const gP=A.p(gStart+0.1,0.9,'softLand');
  const gP2=A.p(tMu,0.5,'snapSettle');
  A.circle(gx,gy,gr,{stroke:'#ffffff',lw:5,fill:'rgba(80,140,220,0.15)'});
  const rot=t*0.6;
  for(let m=-2;m<=2;m++){const off=((m*0.5+rot)%2.5+2.5)%2.5-1.25;const rx=Math.abs(Math.sin(off*1.25))*gr;
    ctx.save();ctx.strokeStyle='#fff';ctx.globalAlpha=0.6*gP;ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(gx,gy,Math.max(1,rx),Math.max(1,gr),0,0,Math.PI*2);ctx.stroke();ctx.restore();}
  A.line([[gx-gr,gy],[gx+gr,gy]],{stroke:'#fff',lw:3,progress:gP});
  A.line([[gx-gr*0.87,gy-gr*0.5],[gx+gr*0.87,gy-gr*0.5]],{stroke:'#fff',lw:2,progress:gP,alpha:0.6});
  A.line([[gx-gr*0.87,gy+gr*0.5],[gx+gr*0.87,gy+gr*0.5]],{stroke:'#fff',lw:2,progress:gP,alpha:0.6});
  if(t>=tMu){
    A.rings(gx,gy,tMu,{count:2,speed:420,gap:50,maxR:260,color:'#ffffff',lw:3});
    A.arrow(500,760,gx-gr-10,760,{progress:gP2,color:acc,lw:6});
    A.label('MUNDO',gx,gy+gr+55,{size:44,bg:acc,color:'#0b1a2e',scale:A.pop(tMu+0.1)});
  }
}
},{x:560,y:770,scale:1-0.4*out,alpha:1-out});
}
// atrapanieblas
if(t>=tCo-0.05){
const s=A.pop(tCo,0.5);
const mx=540,my=740,mw=540,mh=340;
const top=my-mh/2;
A.with(()=>{
const postH=1120-(top-10);
A.rect(mx-mw/2-14,top-10,14,postH,{fill:'#8a9bb5'});
A.rect(mx+mw/2,top-10,14,postH,{fill:'#8a9bb5'});
A.rect(mx-mw/2,top,mw,mh,{fill:'rgba(255,212,0,0.06)',stroke:acc,lw:4});
const gp=A.p(tCo,0.6,'softLand');
for(let x=mx-mw/2;x<=mx+mw/2;x+=27)A.line([[x,top],[x,top+mh]],{stroke:acc,lw:1.5,alpha:0.55,progress:gp});
for(let y=top;y<=top+mh;y+=27)A.line([[mx-mw/2,y],[mx+mw/2,y]],{stroke:acc,lw:1.5,alpha:0.55,progress:gp});
A.rect(mx-mw/2-20,top+mh+6,mw+40,26,{r:12,fill:'#3d7bd9',stroke:'#fff',lw:3});
const lt=t-tCo;
A.particles(16,21,(i,r)=>{const x=mx-mw/2+27*(1+Math.floor(r()*19));const per=0.7+r()*0.5;const ph=((lt+r()*per)%per)/per;const y=top+ph*(mh+10);const rr=4+9*ph;A.drop(x,y,rr,{fill:'#9fd4ff',stroke:'#ffffff'});});
},{x:mx,y:my,scale:s});
A.particles(18,33,(i,r)=>{const y=600+r()*300;const ph=((t*0.9+r())%1);const x=A.lerp(-40,mx-mw/2,ph);A.circle(x,y,6+r()*8,{fill:'#e8f2ff',alpha:0.6*s*(1-ph*0.3)});});
if(t>=tAt){
A.flash(tAt,0.25,0.35);
A.label('ATRAPANIEBLAS',540,480,{size:62,bg:acc,color:'#0b1a2e',scale:A.pop(tAt,0.4)});
A.with(()=>{A.text('?',900,960,{size:240,color:acc,weight:'900',align:'center',stroke:'#0b1a2e',strokeWidth:10});},{x:900,y:900,scale:A.pop(tAt+0.08,0.45),rot:0.15*Math.sin(t*4)});
}
}
